import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.oauth2.jwt.JwtDecoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.servlet.util.matcher.PathPatternRequestMatcher;
import sk.knizat.tennisclub.security.AccessTokenAuthenticationConverter;
import sk.knizat.tennisclub.security.RestAccessDeniedHandler;
import sk.knizat.tennisclub.security.RestAuthenticationEntryPoint;

/**
 * Web security (ARCHITECTURE.md section 5.6): stateless, CSRF off, two filter chains.
 * <ol>
 * <li>{@code POST /api/auth/login}: HTTP Basic against the user accounts (phone number + password), no other
 * authentication accepted.</li>
 * <li>Everything else: bearer JWT access tokens (resource server) with the role matrix
 * {@code permitAll} for auth, OpenAPI and the H2 console; {@code USER|ADMIN} for every {@code GET /api/**},
 * {@code POST /api/reservations} and {@code GET /api/users/me}; {@code ADMIN} for the rest of {@code /api/**}.</li>
 * </ol>
 * Failures are RFC 7807 problems: 401 from {@link RestAuthenticationEntryPoint}, 403 from
 * {@link RestAccessDeniedHandler}.
 */
@Configuration
@RequiredArgsConstructor
public class SecurityConfig {

    static final String LOGIN_PATH = "/api/auth/login";
    static final String[] PUBLIC_PATHS = {"/api/auth/**", "/swagger-ui/**", "/swagger-ui.html", "/v3/api-docs/**"};
    static final String H2_CONSOLE_PATH = "/h2-console/**";
    static final String ROLE_USER = RoleDto.USER.name();
    static final String ROLE_ADMIN = RoleDto.ADMIN.name();

    private final RestAuthenticationEntryPoint authenticationEntryPoint;
    private final RestAccessDeniedHandler accessDeniedHandler;

    /** The H2 console is public (and framed) only when it is enabled, i.e. in the {@code dev} profile. */
    @Value("${spring.h2.console.enabled:false}")
    private boolean h2ConsoleEnabled;

    /** Basic authentication against {@link UserDetailsService} with BCrypt; used only by the login chain. */
    @Bean
    public AuthenticationManager authenticationManager(UserDetailsService userDetailsService,
                                                       PasswordEncoder passwordEncoder) {
        DaoAuthenticationProvider provider = new DaoAuthenticationProvider(userDetailsService);
        provider.setPasswordEncoder(passwordEncoder);
        return new ProviderManager(provider);
    }

    @Bean
    @Order(1)
    public SecurityFilterChain loginFilterChain(HttpSecurity http, AuthenticationManager authenticationManager)
            throws Exception {
        return http
                .securityMatcher(PathPatternRequestMatcher.withDefaults().matcher(HttpMethod.POST, LOGIN_PATH))
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .formLogin(form -> form.disable())
                .authenticationManager(authenticationManager)
                .httpBasic(basic -> basic.authenticationEntryPoint(authenticationEntryPoint))
                .exceptionHandling(handling -> handling.authenticationEntryPoint(authenticationEntryPoint))
                .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
                .build();
    }

    @Bean
    @Order(2)
    public SecurityFilterChain apiFilterChain(HttpSecurity http, JwtDecoder jwtDecoder,
                                              AccessTokenAuthenticationConverter authenticationConverter)
            throws Exception {
        return http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .httpBasic(basic -> basic.disable())
                .formLogin(form -> form.disable())
                // the H2 console renders itself in frames; everywhere else the default DENY stays
                .headers(headers -> headers.frameOptions(
                        frame -> {
                            if (h2ConsoleEnabled) {
                                frame.sameOrigin();
                            }
                        }))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers(PUBLIC_PATHS).permitAll()
                        .requestMatchers(H2_CONSOLE_PATH)
                        .access((authentication, context) -> new AuthorizationDecision(h2ConsoleEnabled))
                        .requestMatchers(HttpMethod.GET, "/api/**").hasAnyRole(ROLE_USER, ROLE_ADMIN)
                        .requestMatchers(HttpMethod.HEAD, "/api/**").hasAnyRole(ROLE_USER, ROLE_ADMIN)
                        .requestMatchers(HttpMethod.POST, "/api/reservations").hasAnyRole(ROLE_USER, ROLE_ADMIN)
                        .requestMatchers("/api/**").hasRole(ROLE_ADMIN)
                        .anyRequest().authenticated())
                .oauth2ResourceServer(oauth2 -> oauth2
                        .jwt(jwt -> jwt.decoder(jwtDecoder).jwtAuthenticationConverter(authenticationConverter))
                        .authenticationEntryPoint(authenticationEntryPoint)
                        .accessDeniedHandler(accessDeniedHandler))
                .exceptionHandling(handling -> handling
                        .authenticationEntryPoint(authenticationEntryPoint)
                        .accessDeniedHandler(accessDeniedHandler))
                .build();
    }
}
package sk.knizat.tennisclub.security;

import org.springframework.security.core.GrantedAuthority;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.userdetails.UserDetails;
import sk.knizat.tennisclub.dto.RoleDto;
import sk.knizat.tennisclub.dto.user.AuthUser;

import java.util.Collection;
import java.util.List;

/**
 * Spring Security adapter over {@link AuthUser}. Named {@code AppUserDetails} because the entity {@code User}
 * clashes with Spring Security's own {@code User}. The username is the phone number, the single authority is
 * {@code ROLE_<role>}, and an account without a password is disabled (it cannot log in).
 */
public final class AppUserDetails implements UserDetails {

    private static final String ROLE_PREFIX = "ROLE_";

    private final AuthUser user;

    public AppUserDetails(AuthUser user) {
        this.user = user;
    }

    public Long getId() {
        return user.id();
    }

    public RoleDto getRole() {
        return user.role();
    }

    @Override
    public Collection<? extends GrantedAuthority> getAuthorities() {
        return List.of(new SimpleGrantedAuthority(ROLE_PREFIX + user.role().name()));
    }

    @Override
    public String getPassword() {
        return user.passwordHash();
    }

    @Override
    public String getUsername() {
        return user.phoneNumber();
    }

    @Override
    public boolean isEnabled() {
        return user.canLogin();
    }

    @Override
    public boolean isAccountNonExpired() {
        return true;
    }

    @Override
    public boolean isAccountNonLocked() {
        return true;
    }

    @Override
    public boolean isCredentialsNonExpired() {
        return true;
    }
}

package sk.knizat.tennisclub.service.impl;

import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import sk.knizat.tennisclub.dao.CourtDao;
import sk.knizat.tennisclub.dao.ReservationDao;
import sk.knizat.tennisclub.dao.SurfaceTypeDao;
import sk.knizat.tennisclub.dto.court.CourtRequest;
import sk.knizat.tennisclub.dto.court.CourtResponse;
import sk.knizat.tennisclub.entity.Court;
import sk.knizat.tennisclub.entity.SurfaceType;
import sk.knizat.tennisclub.exception.ConflictException;
import sk.knizat.tennisclub.exception.NotFoundException;
import sk.knizat.tennisclub.exception.ValidationException;
import sk.knizat.tennisclub.mapper.CourtMapper;
import sk.knizat.tennisclub.service.CourtService;

import java.time.Clock;
import java.time.Instant;
import java.util.List;

/** Default {@link CourtService} backed by {@link CourtDao}. */
@Service
@Transactional
@RequiredArgsConstructor
public class CourtServiceImpl implements CourtService {

    private static final String ENTITY = "Court";

    private final CourtDao courtDao;
    private final SurfaceTypeDao surfaceTypeDao;
    private final ReservationDao reservationDao;
    private final CourtMapper mapper;
    private final Clock clock;

    @Override
    @Transactional(readOnly = true)
    public List<CourtResponse> findAll() {
        return courtDao.findAll().stream().map(mapper::toResponse).toList();
    }

    @Override
    @Transactional(readOnly = true)
    public CourtResponse findById(Long id) {
        return mapper.toResponse(getOrThrow(id));
    }

    @Override
    public CourtResponse create(CourtRequest request) {
        if (courtDao.existsByCourtNumber(request.courtNumber())) {
            throw duplicateNumber(request.courtNumber());
        }
        SurfaceType surfaceType = resolveSurfaceType(request.surfaceTypeId());
        Court entity = mapper.toEntity(request, surfaceType);
        return mapper.toResponse(UniqueKeys.saveOrConflict(() -> courtDao.save(entity),
                duplicateNumber(request.courtNumber()).getMessage()));
    }

    @Override
    public CourtResponse update(Long id, CourtRequest request) {
        Court entity = getOrThrow(id);
        boolean takenByOther = courtDao.findByCourtNumber(request.courtNumber())
                .map(other -> !other.getId().equals(id))
                .orElse(false);
        if (takenByOther) {
            throw duplicateNumber(request.courtNumber());
        }
        SurfaceType surfaceType = resolveSurfaceType(request.surfaceTypeId());
        mapper.updateEntity(entity, request, surfaceType);
        return mapper.toResponse(UniqueKeys.saveOrConflict(() -> courtDao.save(entity),
                duplicateNumber(request.courtNumber()).getMessage()));
    }

    @Override
    public void delete(Long id) {
        Court entity = getOrThrow(id);
        Instant now = clock.instant();
        if (reservationDao.existsUnfinishedByCourt(id, now)) {
            throw new ConflictException(
                    "Court with id " + id + " has unfinished reservations and cannot be deleted");
        }
        courtDao.softDelete(entity, now);
    }

    private Court getOrThrow(Long id) {
        return courtDao.findById(id).orElseThrow(() -> NotFoundException.of(ENTITY, id));
    }

    /** The surface type id comes from the payload, so an unknown or deleted one is a 400, not a 404. */
    private SurfaceType resolveSurfaceType(Long surfaceTypeId) {
        return surfaceTypeDao.findById(surfaceTypeId)
                .orElseThrow(() -> new ValidationException("surfaceTypeId " + surfaceTypeId + " does not exist"));
    }

    private static ConflictException duplicateNumber(Integer courtNumber) {
        return new ConflictException("Court with number " + courtNumber + " already exists");
    }
}
package sk.knizat.tennisclub.controller;

import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.support.ServletUriComponentsBuilder;
import sk.knizat.tennisclub.dto.court.CourtRequest;
import sk.knizat.tennisclub.dto.court.CourtResponse;
import sk.knizat.tennisclub.service.CourtService;

import java.net.URI;
import java.util.List;

/** REST endpoints of court management ({@code /api/courts}). */
@RestController
@RequestMapping("/api/courts")
@RequiredArgsConstructor
@Tag(name = "Courts", description = "Tennis court management")
public class CourtController {

    private final CourtService courtService;

    @GetMapping
    @Operation(summary = "List courts")
    public List<CourtResponse> findAll() {
        return courtService.findAll();
    }

    @GetMapping("/{id}")
    @Operation(summary = "Get a court by id")
    public CourtResponse findById(@PathVariable Long id) {
        return courtService.findById(id);
    }

    @PostMapping
    @Operation(summary = "Create a court")
    public ResponseEntity<CourtResponse> create(@Valid @RequestBody CourtRequest request) {
        CourtResponse created = courtService.create(request);
        URI location = ServletUriComponentsBuilder.fromCurrentRequest()
                .path("/{id}")
                .buildAndExpand(created.id())
                .toUri();
        return ResponseEntity.created(location).body(created);
    }

    @PutMapping("/{id}")
    @Operation(summary = "Update a court")
    public CourtResponse update(@PathVariable Long id, @Valid @RequestBody CourtRequest request) {
        return courtService.update(id, request);
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    @Operation(summary = "Soft-delete a court")
    public void delete(@PathVariable Long id) {
        courtService.delete(id);
    }
}
package sk.knizat.tennisclub.dao;

import sk.knizat.tennisclub.entity.BaseEntity;

import java.time.Instant;
import java.util.List;
import java.util.Optional;

/**
 * Generic persistence operations shared by every DAO. All read methods see only non-deleted rows;
 * deletion is always a soft delete (see {@link BaseEntity#markDeleted(Instant)}).
 *
 * @param <T> entity type
 */
public interface GenericDao<T extends BaseEntity> {

    /**
     * Finds a non-deleted entity by id.
     *
     * @return the entity, or empty when it does not exist or is soft-deleted
     */
    Optional<T> findById(Long id);

    /** Returns all non-deleted entities ordered by id. */
    List<T> findAll();

    /**
     * Persists a new entity ({@code id == null}) or merges a detached/updated one.
     * <p>
     * Updates must follow load-then-modify: load the managed entity via {@link #findById(Long)}, change it and
     * pass it here. Never build a fresh object with an id and merge it: merge copies every field, so
     * {@code createdAt} would be lost on the returned instance and a soft-deleted row would be silently revived.
     *
     * The change is flushed before returning, so lifecycle callbacks (audit timestamps, generated id) have
     * already run on the returned instance.
     *
     * @return the managed instance (same object for persist, possibly a different one for merge)
     */
    T save(T entity);

    /**
     * Soft-deletes the entity: marks it deleted at {@code now} and merges the change.
     * Idempotent for an already deleted entity. Flushed before returning.
     *
     * @param now deletion time supplied by the caller from the application {@code Clock}
     */
    void softDelete(T entity, Instant now);

    /** Tells whether a non-deleted entity with the given id exists. */
    boolean existsById(Long id);
}
package sk.knizat.tennisclub.dao;

import sk.knizat.tennisclub.entity.Reservation;

import java.time.Instant;
import java.util.List;

/** DAO of {@link Reservation}; list queries eagerly fetch court, surface type and user. */
public interface ReservationDao extends GenericDao<Reservation> {

    /**
     * Non-deleted reservations of the court with the given number, oldest first. The court itself may be
     * soft-deleted: history of a removed court stays readable by its number.
     */
    List<Reservation> findByCourtNumberOrderByCreatedAt(Integer courtNumber);

    /**
     * Non-deleted reservations of the non-deleted user with the given phone number, ordered by start time.
     *
     * @param futureOnly when {@code true} only reservations starting strictly after {@code now} are returned
     * @param now        reference time (ignored when {@code futureOnly} is {@code false})
     */
    List<Reservation> findByPhoneNumber(String phoneNumber, boolean futureOnly, Instant now);

    /** All non-deleted reservations ordered by start time. */
    List<Reservation> findAllOrderByStartTime();

    /**
     * Tells whether a non-deleted reservation on the court overlaps the half-open interval
     * {@code [start, end)}: {@code r.startTime < end AND r.endTime > start}. Touching intervals do not overlap.
     *
     * @param excludeReservationId reservation to ignore (the one being updated), may be {@code null}
     */
    boolean existsOverlapping(Long courtId, Instant start, Instant end, Long excludeReservationId);

    /**
     * Tells whether the court has a non-deleted reservation that has not finished yet ({@code endTime > now}).
     * Used to block deletion: an ongoing reservation blocks as well as a future one.
     */
    boolean existsUnfinishedByCourt(Long courtId, Instant now);

    /** Tells whether the user has a non-deleted reservation that has not finished yet ({@code endTime > now}). */
    boolean existsUnfinishedByUser(Long userId, Instant now);
}
package sk.knizat.tennisclub.security;

import org.springframework.core.convert.converter.Converter;
import org.springframework.security.authentication.AbstractAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.oauth2.server.resource.InvalidBearerTokenException;
import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;
import org.springframework.stereotype.Component;

import java.util.List;

/**
 * Turns a decoded bearer JWT into an {@link org.springframework.security.core.Authentication}: the
 * {@code role} claim becomes {@code ROLE_<role>} and the principal name is the subject (phone number).
 * Tokens whose {@code type} is not {@value JwtTokenService#TYPE_ACCESS} (i.e. refresh tokens) are rejected
 * with an {@link InvalidBearerTokenException}, which the resource server reports as 401.
 */
@Component
public class AccessTokenAuthenticationConverter implements Converter<Jwt, AbstractAuthenticationToken> {

    @Override
    public AbstractAuthenticationToken convert(Jwt jwt) {
        if (!JwtTokenService.TYPE_ACCESS.equals(jwt.getClaimAsString(JwtTokenService.CLAIM_TYPE))) {
            throw new InvalidBearerTokenException("Token is not an access token");
        }
        String role = jwt.getClaimAsString(JwtTokenService.CLAIM_ROLE);
        if (role == null) {
            throw new InvalidBearerTokenException("Token has no role claim");
        }
        return new JwtAuthenticationToken(jwt, List.of(new SimpleGrantedAuthority("ROLE_" + role)), jwt.getSubject());
    }
}
